import 'package:flutter/material.dart'; import 'package:go_router/go_router.dart'; import '../../../routes/route_paths.dart'; import '../models/chatbot_models.dart';
class ChatDoctorResultCard extends StatelessWidget { const ChatDoctorResultCard({super.key, required this.doctor, this.onSelect, this.selected = false}); final ChatDoctorResult doctor; final VoidCallback? onSelect; final bool selected; @override Widget build(BuildContext context) { final rtl = Directionality.of(context) == TextDirection.rtl; final name = [(rtl ? doctor.firstNameAr ?? doctor.firstNameEn : doctor.firstNameEn ?? doctor.firstNameAr), (rtl ? doctor.lastNameAr ?? doctor.lastNameEn : doctor.lastNameEn ?? doctor.lastNameAr)].whereType<String>().join(' '); final specialty = rtl ? doctor.specialtyAr ?? doctor.specialtyEn : doctor.specialtyEn ?? doctor.specialtyAr; return Card(color: selected ? Theme.of(context).colorScheme.primaryContainer : null, child: ListTile(selected: selected, onTap: onSelect, title: Text(name.isEmpty ? 'Doctor' : name), subtitle: Text([?specialty, if (doctor.averageRating != null) '${doctor.averageRating!.toStringAsFixed(1)} rating', if (doctor.consultationFee != null) '${doctor.consultationFee!.toStringAsFixed(0)} ILS'].whereType<String>().join(' · ')), trailing: doctor.id.isEmpty ? null : TextButton(onPressed: () => context.push(RoutePaths.doctorDetailPath(doctor.id)), child: const Text('Details')))); } }
